import{_ as t,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Apply Coupon","description":"","frontmatter":{"outline":false,"examples":[{"id":"apply-coupon","title":"Apply Coupon to Cart","description":"Apply a discount coupon code to the shopping cart.","request":"curl -X POST \\"http://localhost/api/shop/apply-coupon\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 62f2b3f5-a455-4c78-93ba-eabca63d32ec\\" \\\\\\n  -d '{\\n        \\"couponCode\\": \\"SAVE20\\"\\n      }'\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 495,\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"itemsCount\\": 1,\\n  \\"subtotal\\": 74.97,\\n  \\"discountAmount\\": 14.99,\\n  \\"taxAmount\\": 0,\\n  \\"shippingAmount\\": 0,\\n  \\"grandTotal\\": 59.98,\\n  \\"formattedSubtotal\\": \\"$74.97\\",\\n  \\"formattedDiscountAmount\\": \\"$14.99\\",\\n  \\"formattedGrandTotal\\": \\"$59.98\\",\\n  \\"couponCode\\": \\"SAVE20\\",\\n  \\"isGuest\\": true\\n}\\n","commonErrors":[{"error":"success false with the message \\"Failed to apply coupon\\"","cause":"The code does not exist, has expired, or the cart does not meet its conditions","solution":"All three fail the same way and still answer 201 — read the success field, not the status code"},{"error":"400 Bad Request — Coupon code is required","cause":"couponCode was missing from the body","solution":"Send couponCode; the field is not named code"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/apply-coupon.md","filePath":"api/rest-api/shop/cart/apply-coupon.md","lastUpdated":1787725411000}`),d={name:"api/rest-api/shop/cart/apply-coupon.md"};function n(r,e,i,c,l,p){return a(),o("div",null,e[0]||(e[0]=[s(`<h1 id="apply-coupon" tabindex="-1">Apply Coupon <a class="header-anchor" href="#apply-coupon" aria-label="Permalink to &quot;Apply Coupon&quot;">​</a></h1><p>Apply a discount coupon code to the shopping cart.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/apply-coupon</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;couponCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SAVE20&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>couponCode</code></td><td>string</td><td>Yes</td><td>The coupon to apply. The field is <code>couponCode</code> — <code>code</code> is not read, and its absence fails with <code>Coupon code is required</code>.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>201 Created</code> carrying the whole recalculated cart — the same object <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> returns, plus two fields describing the attempt.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the coupon was applied.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Coupon applied successfully</code> or <code>Failed to apply coupon</code>.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td>The applied code. <code>null</code> when the attempt failed.</td></tr><tr><td><code>discountAmount</code> / <code>formattedDiscountAmount</code></td><td>number / string</td><td>The discount now on the cart.</td></tr><tr><td><code>grandTotal</code> / <code>formattedGrandTotal</code></td><td>number / string</td><td>The recalculated total.</td></tr></tbody></table><p>A rejected coupon still answers <code>201</code> with the full cart untouched, so the status code alone never tells you whether the discount applied.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Result</th></tr></thead><tbody><tr><td><code>couponCode</code> present</td><td>Missing → <code>400 Coupon code is required</code>.</td></tr><tr><td>The code exists on an active cart rule</td><td>Otherwise <code>success: false</code>, <code>Failed to apply coupon</code>.</td></tr><tr><td>The cart satisfies the rule&#39;s conditions</td><td>Same failure — the message does not distinguish &quot;unknown code&quot; from &quot;conditions not met&quot;.</td></tr></tbody></table><p>Applying a second coupon replaces the first; a cart holds one coupon at a time.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Coupon field at checkout</strong> — post the typed code, then branch on <code>success</code> and re-render the totals straight from the response.</li><li><strong>Show the discount immediately</strong> — the response is the recalculated cart, so no follow-up <a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> is needed.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Branch on <code>success</code>, never on the status code</strong> — a wrong code and a valid one both answer <code>201</code>.</li><li><strong>Use <code>couponCode</code>, not <code>code</code></strong> — the wrong key is treated as a missing coupon.</li><li><strong>Show the store&#39;s own message with care</strong> — one generic failure string covers unknown, expired, and non-qualifying codes, so a UI that says &quot;coupon does not exist&quot; will sometimes be wrong.</li><li><strong>Re-read <code>grandTotal</code> after applying</strong> — the discount changes shipping and tax lines as well as the subtotal.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/remove-coupon.html">Remove Coupon</a> — clear the applied coupon and recalculate</li><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li></ul>`,22)]))}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
